/**
 * @param {number[]} nums
 * @return {number}
 */
var findGCD = function(nums) {
    let min = Infinity;
    let max = -Infinity;

    for (const num of nums) {
        min = Math.min(min, num);
        max = Math.max(max, num);
    }

    return gcd(max, min);
};

const gcd = (a, b) => {
    while (b !== 0) {
        [a, b] = [b, a % b];
    }
    return a;
};
